entries[222458] = { ["name"] = "Geweihte Schritte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Verziert (2)\nFüße Platte\n4356 Rüstung\n+1.597 [Stärke oder Intelligenz]\n+7.311 Ausdauer\n+ 546 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 546.\nHaltbarkeit 80 / 80\nAnlegen: Wenn Ihr Schaden erleidet, habt Ihr die Chance, von 'Geweihter Raschheit' erfüllt zu werden. Gewährt Euch 46 Geschwindigkeit, bis zu 10-mal stapelbar.\n\nWenn Ihr 10 Stapel gesammelt habt, entfesselt Ihr die gespeicherte Energie und verursacht ( 1 * 374029 ) Heiligschaden, aufgeteilt unter allen Gegnern innerhalb von 10 Metern.\nVerkaufspreis:" }
entries[222459] = { ["name"] = "Beledars Bollwerk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Verziert (2)\nSchildhand Schild\n20422 Rüstung\n+1.065 Stärke\n+3.266 Intelligenz\n+4.874 Ausdauer\nErhöht Eure kritische Trefferwertung um + 281.\n+ 447 Vielseitigkeit\nHaltbarkeit 120 / 120\nAnlegen: Beim Erleiden von Schaden besteht eine Chance, dass ' Beledars Segen ' gewährt wird, was 15 Sek. lang die Vielseitigkeit um 823 erhöht.\n\nWenn Ihr Euch einem Gruppen- oder Schlachtzugsmitglied bis auf 3 Meter annähert, wird auch ihm ein Anteil von ' Beledars Segen ' gewährt und Ihr profitiert für die verbleibende Dauer beide vom Effekt.\nVerkaufspreis:" }
entries[222463] = { ["name"] = "Entziehendes Stilett", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Verziert (2)\nEinhändig Dolch\n1,415 - 2,941 Schaden Geschwindigkeit 1.80\n(1,210 Schaden pro Sekunde)\n+1.065 Beweglichkeit\n+4.874 Ausdauer\nErhöht Eure kritische Trefferwertung um + 364.\nErhöht Eure Meisterschaftswertung um + 364.\nHaltbarkeit 80 / 80\nAnlegen: Eure Schadenszauber und -fähigkeiten haben eine Chance, Euch 119032 Gesundheit zu entziehen und 3 Sek. lang in die Leere zu werfen.\n\nBei ihrer Rückkehr fügt Ihr zufälligen Gegnern innerhalb von 30 Metern ( 1 * 257929 ) Schaden zu.\n\nDies ist eine nerubische Verzierung.\nVerkaufspreis:" }
