entries[222906] = { ["name"] = "Plumpe Schnappkrabbe", ["text"] = "Einzigartig (5)\n\"Eine plumpe, kleine, wütende Krabbe, die wehrlos wirkt... bis ihre Zangen Euren Finger greifen. Autsch!\"\nVerkaufspreis:" }
