entries[222920] = { ["name"] = "Fesselzahnblattnasenfleisch", ["text"] = "Questgegenstand\n\"Eine überraschend fleischige Keule für ein so kleines Tier.\"" }
entries[222921] = { ["name"] = "Zerfleischte Kobyssinnereien", ["text"] = "Questgegenstand\n\"Ein groteskes Buffet mit verschiedenen Organen der Kobyss.\"" }
entries[222922] = { ["name"] = "Schwere Kiste", ["text"] = "80 ( 80)\n\"Können Ausrüstung, Rezepte, Währungen, Sammelgegenstände und Kuriositäten enthalten.\"" }
entries[222923] = { ["name"] = "Expeditionsbeute", ["text"] = "\"Kann Ausrüstung, exotische Reagenzien, Sammelgegenstände und geheime Rezepte enthalten.\"" }
entries[222924] = { ["name"] = "Innereien eines Lebersuchers", ["text"] = "Questgegenstand\nEinzigartig\n\"Obwohl sie voller zerkauter Lebern anderer ist, ist die Leber von Lebersuchern trotzdem recht klein.\"" }
entries[222925] = { ["name"] = "Robuste Efeufaser", ["text"] = "Questgegenstand\n78 ( 78)\n\"Dieser Efeu ist praktisch schon ein Seil, bevor er überhaupt bearbeitet wird.\"" }
entries[222926] = { ["name"] = "Magen eines Beinkauers", ["text"] = "Questgegenstand\nEinzigartig\n\"Hier ein Brocken Beinfleisch. Und außerdem Brocken von Arm, Auge, Gesicht... eigentlich von allem.\"" }
entries[222927] = { ["name"] = "Verwitterte Münzkassette", ["text"] = "\"Enthält verschiedene Währungen wie Gold, Lorenmünzen, Tapferkeitssteine, Resonanzkristalle und verwitterte Wappen.\"" }
