entries[222953] = { ["name"] = "Lichtgebadete Lotusableger", ["text"] = "Questgegenstand\n78 ( 78)\n\"Leuchtet leicht. Schmeckt dezent nach Friedensblume, aber mit einem Hauch Zitrus.\"" }
