entries[223137] = { ["name"] = "Formel: Armschienen - Gesang des gepanzerten Lebensraubs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Gesang des gepanzerten Lebensraubs' durchführt.\nNerubische Neuheiten - Tertiäre Trivialitäten\n\nArmschienen dauerhaft mit uralter Magie verzaubern, die vor Macht skandiert, sodass sie 1425 Lebensraub gewähren. Kann nicht auf Gegenstände unter Stufe 350 angewandt werden.\nBenötigt Verzauberkunst von Khaz Algar (25)\nVerkaufspreis:" }
entries[223138] = { ["name"] = "Formel: Umhang - Gesang der geflügelten Anmut", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Gesang der geflügelten Anmut' durchführt.\nNerubische Neuheiten - Tertiäre Trivialitäten\n\nEinen Umhang dauerhaft mit uralter Magie verzaubern, die vor Macht skandiert. Gewährt 380 Vermeidung und verringert Fallschaden um 0%. Kann nicht auf Gegenstände unter Stufe 350 angewandt werden.\nBenötigt Verzauberkunst von Khaz Algar (25)\nVerkaufspreis:" }
entries[223139] = { ["name"] = "Formel: Umhang - Gesang der räuberischen Fangzähne", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Gesang der räuberischen Fangzähne' durchführt.\nNerubische Neuheiten - Tertiäre Trivialitäten\n\nEinen Umhang dauerhaft mit uralter Magie verzaubern, die vor Macht skandiert. Gewährt 715 Lebensraub und heilt außerhalb des Kampfes alle 5 Sek. um 174266 Gesundheit. Kann nicht auf Gegenstände unter Stufe 350 angewandt werden.\nBenötigt Verzauberkunst von Khaz Algar (25)\nVerkaufspreis:" }
entries[223140] = { ["name"] = "Formel: Umhang - Gesang der grabenden Schnelligkeit", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Gesang der grabenden Schnelligkeit' durchführt.\nNerubische Neuheiten - Tertiäre Trivialitäten\n\nEinen Umhang dauerhaft mit uralter Magie verzaubern, die vor Macht skandiert. Erhöht die Geschwindigkeit um 175 und die Abklingzeitrate Eures Ruhesteins um 0%, während Ihr in Khaz Algar seid. Kann nicht auf Gegenstände unter Stufe 350 angewandt werden.\nBenötigt Verzauberkunst von Khaz Algar (25)\nVerkaufspreis:" }
entries[223141] = { ["name"] = "Formel: Ring - Verfluchter kritischer Treffer", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Verfluchter kritischer Treffer' durchführt.\nNerubische Neuheiten - Verfluchter Gesang\n\nEinen Ring dauerhaft mit einem verfluchten Spruch verzaubern, der Euch -53 Eures Tempos entzieht und dafür Euren kritischen Trefferwert um 180 erhöht. Kann nicht auf Gegenstände unter Stufe 350 angewandt werden.\nBenötigt Verzauberkunst von Khaz Algar (25)\nVerkaufspreis:" }
entries[223142] = { ["name"] = "Formel: Ring - Verfluchte Meisterschaft", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Verfluchte Meisterschaft' durchführt.\nNerubische Neuheiten - Verfluchter Gesang\n\nEinen Ring dauerhaft mit einem verfluchten Spruch verzaubern, der Euch -53 kritischen Trefferwert entzieht und dafür 180 Meisterschaft gewährt. Kann nicht auf Gegenstände unter Stufe 350 angewandt werden.\nBenötigt Verzauberkunst von Khaz Algar (25)\nVerkaufspreis:" }
entries[223143] = { ["name"] = "Formel: Ring - Verfluchte Vielseitigkeit", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Verfluchte Vielseitigkeit' durchführt.\nNerubische Neuheiten - Verfluchter Gesang\n\nEinen Ring dauerhaft mit einem verfluchten Spruch verzaubern, der Euch -53 Meisterschaft entzieht und dafür 180 Vielseitigkeit gewährt. Kann nicht auf Gegenstände unter Stufe 350 angewandt werden.\nBenötigt Verzauberkunst von Khaz Algar (25)\nVerkaufspreis:" }
entries[223144] = { ["name"] = "Formel: Waffe - Autorität der Tiefen", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Autorität der Tiefen' durchführt.\nNerubische Neuheiten\n\nEine Waffe dauerhaft mit der Autorität der Tiefen verzaubern. Gegnern damit Schaden zuzufügen, kann die Autorität aktivieren, um die Ziele mit 'Erstickende Dunkelheit' zu belegen, die ihnen regelmäßig ( 1 * 24502) Schattenschaden zufügt. Die Dunkelheit lässt sich bis zu 3-mal vertiefen. Kann nicht auf Gegenstände unter Stufe 350 angewandt werden.\nBenötigt Verzauberkunst von Khaz Algar (25)\nVerkaufspreis:" }
