entries[223146] = { ["name"] = "Säckchen mit sturmgeborenen Samenkörnern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Pflanzt ein Samenkorn ein. (1 Min Abklingzeit)\n\"Die Macht eines Sturmes kann sowohl zur Schöpfung als auch zur Zerstörung eingesetzt werden.\"\nVerkaufspreis:" }
entries[223153] = { ["name"] = "Zügel der gleitenden Weidenbiene", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses bescheidene Bienchen träumt von freien Himmeln. Ob mit oder ohne Abenteurer an ihrer Seite, ist für sie dabei nicht von Bedeutung.\"\nVerkäufer:\nCendvin\nZone:\nDie Insel von Dorn\nKosten:\n900" }
