entries[223157] = { ["name"] = "Brustplatte des Schmieds", ["text"] = "Questgegenstand\n\"Faerin erkennt, dass diese Brustplatte Ryton Schwarzholm gehört. Sie ist eines seiner Meisterstücke. Die blutbedeckten Kratzer lassen keine Zweifel am Schicksal des Schmieds.\"" }
entries[223158] = { ["name"] = "Wütende Glutbiene", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Art der Glutbienen ist genauso temperamentvoll wie ihre Flammen heiß sind und kann nur von jenen gebändigt werden, die ihr unersättliches Verlangen nach Gewalt teilen.\"\nErfolg:\nGrobius' Gebot\nKategorie:\nWelt" }
