entries[223317] = { ["name"] = "Zinnoberroter Kaiserluchs", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 18 bei den Arathi von Heilsturz.\nBenötigt Ruhmrang 21 bei den Arathi von Heilsturz.\n\n\"Kaiserluchse sind die besten Gefährten der Arathi, und das nicht nur auf dem Schlachtfeld. Leider ist der vorherige Besitzer dieses Luchses in der Schlacht gefallen.\"\nVerkäufer:\nAuralia Stahlstoß\nZone:\nHeilsturz\nKosten:\n8.125" }
entries[223318] = { ["name"] = "Furchtloser Kaiserluchs", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diesem Luchsharnisch wurden nahezu alle Abzeichen abgerissen. Auf der letzten verbleibenden Marke steht \"Furchtlos\".\"\nBeute von:\nVerbreitung des Lichts\nZone:\nHeilsturz" }
entries[223322] = { ["name"] = "Hannans Sense", ["text"] = "Questgegenstand\nBenutzen: Nutzt die Sense der Haranir, um die Spuren von Orweynas Magie einzusammeln.\n\"Eine Waffe der Harronir, die natürliche Magie für die Wiederverwertung absorbieren kann.\"" }
entries[223339] = { ["name"] = "Trishi", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
