entries[223888] = { ["name"] = "Instabiles Dynamit", ["text"] = "Wird beim Aufheben gebunden\n\"Diese lausige Stange Dynamit sieht so aus, als könnte sie jede Sekunde in die Luft fliegen und droht, in Euren Händen zu zerkrümeln.\"" }
entries[223889] = { ["name"] = "Flammenberührte Waffen", ["text"] = "Questgegenstand\n\"Waffen gehärtet in der heiligen Flamme. Das Beste, was die Arathi zu bieten haben.\"" }
entries[223890] = { ["name"] = "Robustes Efeuseil", ["text"] = "Questgegenstand\n\"Ein erstaunlich starkes, aber dennoch geschmeidiges Seil. Es ist nicht schwer zu sehen, warum Aurelia Euch darum gebeten hat, die Materialien dafür zu sammeln.\"" }
entries[223891] = { ["name"] = "Feuriger Kern", ["text"] = "Questgegenstand\nEinzigartig (4)\n73 ( 73)\n\"Unter einer Schicht aus Staub und Sand verbirgt sich ein harter Elementarkern, der leicht in Eurer Hand bebt.\"" }
entries[223892] = { ["name"] = "Verschiedene Gewürze", ["text"] = "Questgegenstand\n\"Ein aromatischer Duft steigt Euch in die Nase. Es ist nicht schwer, sich die verschiedenen Gerichte vorzustellen, die man damit kochen könnte.\"" }
