entries[223955] = { ["name"] = "Rezept: Feines Eierpulver", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man feines Eierpulver herstellt.\nRezept für 5 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBenötigt Kochkunst von Khaz Algar (35)\nVerkaufspreis:\nFeines Eierpulver\nHandwerksmaterial\n\"Wird von Spielercharakteren gewonnen, die den Beruf der Kochkunst ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[223956] = { ["name"] = "Rezept: Alles-am-Stock", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Alles-am-Stock herstellt.\nRezept für 2 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBenötigt Kochkunst von Khaz Algar (35)\nVerkaufspreis:\nAlles-am-Stock\nWird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und erhaltet die Werte einer zufälligen Mahlzeit aus Khaz Algar.\n\"Könnte alles sein!\"\nVerkaufspreis:\nBenötigt Geronnenes Eigelb" }
entries[223957] = { ["name"] = "Rezept: Proteinschlabber", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Proteinschlabber herstellt.\nRezept für 1 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBenötigt Kochkunst von Khaz Algar (35)\nVerkaufspreis:\nProteinschlabber\nBenutzen: Stellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr Satt , Euer niedrigster Sekundärwert wird um [Quellwert] erhöht und Ihr werdet um 1% größer. Hält 15 Min. lang an.\n\"Er blubbert.\"\nVerkaufspreis:\nBenötigt Feines Eierpulver (5)", ["unresolvedValues"] = true }
