entries[223968] = { ["name"] = "Schwammschlemmerei", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und Euer niedrigster Sekundärwert wird 15 Min. lang um [Quellwert] erhöht.\nVerkaufspreis:", ["unresolvedValues"] = true }
