entries[223971] = { ["name"] = "Azj-Kahet-Spezial", ["text"] = "Benutzen: Erhöht Eure Bewegungsgeschwindigkeit um 20%, während Ihr in der Stadt der Fäden seid. Kann nur im Freien eingesetzt werden.\n\"Stadtschlemmerei!\"\nVerkaufspreis:" }
entries[223972] = { ["name"] = "Gesprungene Weberschale", ["text"] = "\"Warum irgendwer ein gesplittertes Ei kaufen würde bleibt ein Rätsel.\"\nVerkaufspreis:" }
entries[223973] = { ["name"] = "Klebriger Gespinstsack", ["text"] = "\"Die Überreste des Äußeren kleben weiterhin an jeder Oberfläche, die er berührt.\"\nVerkaufspreis:" }
entries[223974] = { ["name"] = "Zappelndes Ovoid", ["text"] = "\"Wenn es sich mal beruhigen könnte, wäre das großartig.\"\nVerkaufspreis:" }
