entries[224007] = { ["name"] = "Verwendungen für übrig gebliebene Hüllen (Wie man sie auseinandernimmt)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Kürschnereiwissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Kürschnerei von Khaz Algar (1)\n\"Ein recht detaillierter Leitfaden dazu, wie man die Überreste einer Arachnoidenmahlzeit nutzbringend einsetzt. Halbwegs nützlich für Kürschner, eklig für alle.\"\nVerkaufspreis:" }
