entries[224023] = { ["name"] = "Kräutertechniken zur Einbalsamierung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Kräuterkundewissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Kräuterkunde von Khaz Algar (1)\n\"Ein kleines Buch, das beschreibt, wie man seltene Kräuter aus Khaz Algar und Nordend einsetzt, um einen Leichnam perfekt zu konservieren und dessen Geschmack zu bewahren. Könnte für Kräuterkundler nützlich sein.\"\nVerkaufspreis:" }
entries[224024] = { ["name"] = "Theorien der körperlichen Transmutation, Kapitel 8", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Alchemiewissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Alchemie von Khaz Algar\n(1)\n\"Abstrakte Theorien über die alchemistischen Nebenwirkungen der permanenten Verwandlung des eigenen Körpers. Könnte für Alchemisten nützlich sein.\"\nVerkaufspreis:" }
entries[224025] = { ["name"] = "Knisternder Splitter", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (10)\nBenutzen: Kombiniert 10 knisternde Splitter, um ein Sturmgefäß herzustellen, das Alunira aus ihrem Gefängnis befreien könnte.\n\"Selbst in seinem inaktiven Zustand, kann man den Zorn eines Sturms unter seiner Oberfläche wüten hören.\"" }
entries[224026] = { ["name"] = "Sturmgefäß", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Entfernt den schützenden Sturmschleier von Alunira.\n\"Kann große Mengen an Sturmenergie speichern.\"" }
