entries[224036] = { ["name"] = "Und damit ist das Netz im Kasten!", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Schneidereiwissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Schneiderei von Khaz Algar (1)\n\"Ein Buch, dass die lange Geschichte der nerubischen Tradition des Webens fürs Theater behandelt. Könnte nützliche Lektionen für Schneider enthalten.\"\nVerkaufspreis:" }
