entries[224041] = { ["name"] = "Heilige Brigade", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft einen Klecks heiliges Öl, das eine Explosion auslöst, die allen Gegnern innerhalb von 6 Metern 29775 Heiligfeuerschaden zufügt, sie zurückstößt und ihre Bewegungsgeschwindigkeit 8 Sek. lang um 30% verringert.\n\nDer Rückstoßeffekt ist bei gegnerischen Spielercharakteren wirksamer." }
entries[224042] = { ["name"] = "Gierige Rückstände", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Die Rückstände der Nebelbestie erfüllen Euch und erhöhen Euren Schaden 30 Sek. lang um 5%." }
entries[224043] = { ["name"] = "Ausgehungerte Rückstände", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Die Rückstände der Nebelbestie erfüllen Euch und erhöhen Eure Vielseitigkeit 30 Sek. lang um 10%." }
entries[224044] = { ["name"] = "Verschlingende Rückstände", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Die Rückstände der Nebelbestie erfüllen Euch und verringern Euren erlittenen Schaden 30 Sek. lang um 15%." }
entries[224045] = { ["name"] = "Tanggriff", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Macht alle Gegner innerhalb von 6 Metern 15 Sek. lang bewegungsunfähig. Schaden kann den Effekt vorzeitig abbrechen. Bewegungsunfähige Ziele erleiden 10% mehr Schaden durch Euch." }
entries[224046] = { ["name"] = "Sandtornado", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschüttet Gegner im Umkreis von 10 Metern mit Sand, der 278825 Naturschaden verursacht, sie um 40% verlangsamt und ihre Chance auf einen kritischen Treffer 6 Sek. lang um 15% verringert." }
entries[224047] = { ["name"] = "Wasserschlag", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stößt das aktuelle gegnerische Ziel zurück und fügt ihm 174266 Frostschaden zu. Der Rückstoß ist wirksamer bei Spielercharakteren." }
entries[224048] = { ["name"] = "Elektrischer Schock", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verursacht 46925 Naturschaden, stößt Gegner zurück und verlangsamt sie 8 Sek. lang um 30%." }
entries[224049] = { ["name"] = "Netzziehen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zieht einen Gegner innerhalb von 40 Metern zum Zaubernden und betäubt ihn vorübergehend." }
entries[224050] = { ["name"] = "Gespinstglitzer: Hübsch und mächtig", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Verzauberkunstwissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Verzauberkunst von Khaz Algar (1)\n\"Ein Werbepaket mit Vorschlägen zur Verzauberung der eigenen Netze. Könnte für Verzauberer nützlich sein.\"\nVerkaufspreis:" }
entries[224051] = { ["name"] = "Leicht angekaute Feldfrüchte", ["text"] = "Questgegenstand\n\"Für einen Eintopf oder eine Pastete bestimmt noch zu gebrauchen...\"" }
entries[224052] = { ["name"] = "Uhren, Getriebe, Zahnräder und Beine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Ingenieurskunstwissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Ingenieurskunst von Khaz Algar (1)\n\"Ein überraschend aufschlussreiches Buch, das nerubischen Kindern die Konzepte der Ingenieurskunst näherbringt. Könnte für Ingenieure trotzdem nützlich sein.\"\nVerkaufspreis:" }
entries[224053] = { ["name"] = "Acht Ansichten zur Verteidigung gegen feindliche Runen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Inschriftenkundewissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Inschriftenkunde von Khaz Algar (1)\n\"Dieser Foliant trägt den Untertitel \"Lektionen aus dem Fall von Ahn-Kahet\" und untersucht mögliche Wege, die Runenmacht des Lichkönigs und seiner Diener zu stören und abzulenken. Könnte für Schreiber nützlich sein.\"\nVerkaufspreis:" }
entries[224054] = { ["name"] = "Aufstrebende Kristalle der Oberflächenbewohner", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Juwelierskunstwissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Juwelierskunst von Khaz Algar\n(1)\n\"Ein frisch gedruckter Handzettel, der sich mit dem Einsatz von Resonanzkristallen in nerubischen Arbeiten mit Edelsteinen beschäftigt. Nützlich für Juwelenschleifer.\"\nVerkaufspreis:" }
entries[224055] = { ["name"] = "Ein steiniger Start", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Bergbauwissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Bergbau von Khaz Algar (1)\n\"Ein Foliant mit nerubischen Bergbautechniken, der für einen Gesellen gedacht ist, der das Handwerk noch erlernt. Nützlich für Minenarbeiter.\"\nVerkaufspreis:" }
entries[224056] = { ["name"] = "Verwendungen für übrig gebliebene Hüllen (nachdem Ihr sie auseinandergenommen habt)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Studieren, um Euer Lederverarbeitungswissen von Khaz Algar um 10 zu erhöhen.\nBenötigt Lederverarbeitung von Khaz Algar (1)\n\"Ein grausiger Foliant, der von der produktiven Verstümmelung von Leichen handelt, um nützliche Lederarbeiten zu erschaffen. Er enthält Informationen zur Nutzung von Allianz- und Hordenleichnamen. Nützlich für Lederverarbeiter mit starkem Magen.\"\nVerkaufspreis:" }
entries[224057] = { ["name"] = "Professor Dozentaurs streng geheimer Leitfaden für die Welt der Alchemie von Khaz Algar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erhaltet 1000 Spezialisierungspunkte für die Alchemie von Khaz Algar.\nBenötigt Alchemie von Khaz Algar\n(15)\n\"Schon dieses Buch in Händen zu halten kommt Euch wie mieser Betrug vor, aber es spricht sicher nichts dagegen, kurz einen Blick hineinzuwerfen.\"" }
