entries[224068] = { ["name"] = "Professor Dozentaurs Gehirn über Khaz Algar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Setzt Eure Stufe in den von Euch erlernten Handwerksfertigkeiten von Khaz Algar auf das Maximum und lehrt Euch alle dazugehörigen Rezepte. (2 Min Abklingzeit)\n\"Und jetzt wisst Ihr, warum Juniorprofessor Dozentaur Euch die ganze Zeit geholfen hat.\"" }
entries[224069] = { ["name"] = "Verzaubertes verwittertes Vorbotenwappen", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+100 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"\nVerkaufspreis:" }
entries[224070] = { ["name"] = "Jankys Feinstes", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bietet ein tröstendes Licht selbst in der dunkelsten Mine. Erhöht die Bewegungsgeschwindigkeit um 25% und verringert den erlittenen Schattenschaden um 25%.\nHält 10 Min. lang an.\nNur in Khaz Algar nutzbar.\nVerkaufspreis:" }
entries[224071] = { ["name"] = "Funkenspuckerkerze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verursacht beim Angreifen gelegentlich zusätzlichen Feuerschaden.\nHält 10 Min. lang an.\nNur in Khaz Algar nutzbar.\nVerkaufspreis:" }
