entries[224074] = { ["name"] = "Opalbergbauwerkzeuge", ["text"] = "Questgegenstand\n\"Eine Auswahl an Spitzhacken und Meißeln, die auf das Extrahieren von Opalen ausgelegt ist.\"" }
entries[224075] = { ["name"] = "Großschwert des Zeitläufers", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+25 Stärke\n+25 Beweglichkeit\n+34 Intelligenz\n80 ( 80)" }
